CREATE TABLE governance_commands (
  id uuid PRIMARY KEY,
  environment_id uuid NOT NULL REFERENCES environments(id),
  deployment_set_id uuid NOT NULL REFERENCES deployment_sets(id),
  action text NOT NULL,
  target_contract_key text NOT NULL,
  target_address evm_address NOT NULL,
  selector varchar(10) NOT NULL CHECK (selector ~ '^0x[0-9a-f]{8}$'),
  parameters jsonb NOT NULL,
  dividend_publish_preflight_id uuid REFERENCES dividend_publish_preflights(id),
  dividend_artifact_id uuid,
  dividend_artifact_sha256 varchar(64) CHECK (dividend_artifact_sha256 ~ '^[0-9a-f]{64}$'),
  dividend_expected_merkle_root evm_hash,
  dividend_expected_total_reward_raw uint256_numeric,
  request_hash varchar(64) NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
  requested_by uuid NOT NULL REFERENCES admin_users(id),
  state text NOT NULL CHECK (state IN (
    'CREATED','VALIDATED','PENDING_APPROVAL','APPROVED','QUEUED','SIGNING',
    'SUBMITTED','CONFIRMED','FINALIZED','REJECTED','CANCELLED','FAILED','EXPIRED'
  )),
  expires_at timestamptz,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  FOREIGN KEY (
    dividend_publish_preflight_id,
    dividend_artifact_id,
    dividend_artifact_sha256,
    dividend_expected_merkle_root,
    dividend_expected_total_reward_raw
  ) REFERENCES dividend_publish_preflights(
    id,
    artifact_id,
    artifact_sha256,
    expected_merkle_root,
    expected_total_reward_raw
  ),
  CHECK (
    action <> 'DIVIDEND_PUBLISH'
    OR (
      dividend_publish_preflight_id IS NOT NULL
      AND dividend_artifact_id IS NOT NULL
      AND dividend_artifact_sha256 IS NOT NULL
      AND dividend_expected_merkle_root IS NOT NULL
      AND dividend_expected_total_reward_raw IS NOT NULL
    )
  )
);

ALTER TABLE dividend_epochs
  ADD CONSTRAINT dividend_epochs_current_publish_command_fk
  FOREIGN KEY (current_publish_command_id) REFERENCES governance_commands(id);

CREATE OR REPLACE FUNCTION bind_current_dividend_publish_command(
  p_epoch_id uuid,
  p_command_id uuid,
  p_updated_at timestamptz
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = binggoplus_v2, pg_temp
AS $$
DECLARE
  epoch_state text;
  existing_command_id uuid;
BEGIN
  IF session_user <> 'bgp_api' THEN
    RAISE EXCEPTION 'only bgp_api may bind a current dividend publish command'
      USING ERRCODE = '42501';
  END IF;

  SELECT state, current_publish_command_id
    INTO epoch_state, existing_command_id
  FROM dividend_epochs
  WHERE id = p_epoch_id
  FOR UPDATE;

  IF NOT FOUND OR epoch_state <> 'APPROVED' OR existing_command_id IS NOT NULL THEN
    RAISE EXCEPTION 'publish command binding requires an approved epoch without a current attempt'
      USING ERRCODE = '55000';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM governance_commands command
    JOIN dividend_publish_preflights preflight
      ON preflight.id = command.dividend_publish_preflight_id
    WHERE command.id = p_command_id
      AND command.action = 'DIVIDEND_PUBLISH'
      AND command.state IN ('CREATED', 'VALIDATED', 'PENDING_APPROVAL', 'APPROVED')
      AND preflight.dividend_epoch_id = p_epoch_id
  ) THEN
    RAISE EXCEPTION 'current publish command must be an unsigned command bound to this epoch'
      USING ERRCODE = '55000';
  END IF;

  UPDATE dividend_epochs
  SET current_publish_command_id = p_command_id,
      updated_at = p_updated_at
  WHERE id = p_epoch_id;
END;
$$;

CREATE UNIQUE INDEX one_dividend_publish_command_per_preflight
  ON governance_commands(dividend_publish_preflight_id)
  WHERE action = 'DIVIDEND_PUBLISH'
    AND dividend_publish_preflight_id IS NOT NULL;

CREATE OR REPLACE FUNCTION reject_governance_command_binding_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF ROW(
    NEW.environment_id,
    NEW.deployment_set_id,
    NEW.action,
    NEW.target_contract_key,
    NEW.target_address,
    NEW.selector,
    NEW.parameters,
    NEW.request_hash,
    NEW.requested_by,
    NEW.expires_at,
    NEW.created_at,
    NEW.dividend_publish_preflight_id,
    NEW.dividend_artifact_id,
    NEW.dividend_artifact_sha256,
    NEW.dividend_expected_merkle_root,
    NEW.dividend_expected_total_reward_raw
  ) IS DISTINCT FROM ROW(
    OLD.environment_id,
    OLD.deployment_set_id,
    OLD.action,
    OLD.target_contract_key,
    OLD.target_address,
    OLD.selector,
    OLD.parameters,
    OLD.request_hash,
    OLD.requested_by,
    OLD.expires_at,
    OLD.created_at,
    OLD.dividend_publish_preflight_id,
    OLD.dividend_artifact_id,
    OLD.dividend_artifact_sha256,
    OLD.dividend_expected_merkle_root,
    OLD.dividend_expected_total_reward_raw
  ) THEN
    RAISE EXCEPTION 'governance command execution binding is immutable'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER governance_commands_binding_guard
BEFORE UPDATE OF
  environment_id,
  deployment_set_id,
  action,
  target_contract_key,
  target_address,
  selector,
  parameters,
  request_hash,
  requested_by,
  expires_at,
  created_at,
  dividend_publish_preflight_id,
  dividend_artifact_id,
  dividend_artifact_sha256,
  dividend_expected_merkle_root,
  dividend_expected_total_reward_raw
ON governance_commands
FOR EACH ROW
EXECUTE FUNCTION reject_governance_command_binding_mutation();

CREATE TABLE governance_command_cancellation_requests (
  id uuid PRIMARY KEY,
  command_id uuid NOT NULL UNIQUE REFERENCES governance_commands(id),
  requested_by uuid NOT NULL REFERENCES admin_users(id),
  reason text NOT NULL CHECK (length(reason) BETWEEN 1 AND 2000),
  request_hash varchar(64) NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
  state text NOT NULL CHECK (state IN ('REQUESTED', 'CONSUMED', 'REJECTED')),
  created_at timestamptz NOT NULL,
  resolved_at timestamptz,
  CHECK ((state = 'REQUESTED' AND resolved_at IS NULL) OR (state IN ('CONSUMED', 'REJECTED') AND resolved_at IS NOT NULL))
);

CREATE OR REPLACE FUNCTION enforce_governance_command_state_transition()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF current_user = 'bgp_migrator' THEN
    RETURN NEW;
  END IF;

  IF NEW.state = OLD.state THEN
    RETURN NEW;
  END IF;

  IF current_user = 'bgp_api' THEN
    IF NOT (
      (OLD.state = 'CREATED' AND NEW.state IN ('VALIDATED', 'REJECTED', 'EXPIRED'))
      OR (OLD.state = 'VALIDATED' AND NEW.state IN ('PENDING_APPROVAL', 'APPROVED', 'REJECTED', 'EXPIRED'))
      OR (OLD.state = 'PENDING_APPROVAL' AND NEW.state IN ('APPROVED', 'REJECTED', 'EXPIRED'))
    ) THEN
      RAISE EXCEPTION 'bgp_api cannot apply governance command transition % -> %', OLD.state, NEW.state
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  IF current_user = 'bgp_reconciler' THEN
    IF NOT (
      (OLD.state = 'CREATED' AND NEW.state = 'CANCELLED')
      OR (OLD.state = 'VALIDATED' AND NEW.state = 'CANCELLED')
      OR (OLD.state = 'PENDING_APPROVAL' AND NEW.state = 'CANCELLED')
      OR (OLD.state = 'APPROVED' AND NEW.state IN ('QUEUED', 'CANCELLED', 'EXPIRED'))
      OR (OLD.state = 'QUEUED' AND NEW.state IN ('SIGNING', 'CANCELLED', 'FAILED', 'EXPIRED'))
      OR (OLD.state = 'SIGNING' AND NEW.state IN ('SUBMITTED', 'FAILED'))
      OR (OLD.state = 'SUBMITTED' AND NEW.state IN ('CONFIRMED', 'FAILED'))
      OR (OLD.state = 'CONFIRMED' AND NEW.state IN ('FINALIZED', 'FAILED'))
    ) THEN
      RAISE EXCEPTION 'bgp_reconciler cannot apply governance command transition % -> %', OLD.state, NEW.state
        USING ERRCODE = '55000';
    END IF;
    IF NEW.state = 'CANCELLED' AND NOT EXISTS (
      SELECT 1 FROM governance_command_cancellation_requests request
      WHERE request.command_id = OLD.id AND request.state = 'REQUESTED'
    ) THEN
      RAISE EXCEPTION 'reconciler cancellation requires a pending immutable cancellation request'
        USING ERRCODE = '55000';
    END IF;
    IF OLD.state = 'QUEUED' AND NEW.state = 'SIGNING' AND EXISTS (
      SELECT 1 FROM governance_command_cancellation_requests request
      WHERE request.command_id = OLD.id AND request.state = 'REQUESTED'
    ) THEN
      RAISE EXCEPTION 'queued command with a pending cancellation request cannot enter signing'
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'role % cannot update governance command state', current_user
    USING ERRCODE = '42501';
END;
$$;

CREATE TRIGGER governance_commands_state_transition_guard
BEFORE UPDATE OF state ON governance_commands
FOR EACH ROW
EXECUTE FUNCTION enforce_governance_command_state_transition();

CREATE OR REPLACE FUNCTION enforce_governance_command_cancellation_request_boundary()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  command_state text;
BEGIN
  IF current_user = 'bgp_migrator' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF current_user <> 'bgp_api' OR NEW.state <> 'REQUESTED' OR NEW.resolved_at IS NOT NULL THEN
      RAISE EXCEPTION 'only bgp_api may create a pending cancellation request'
        USING ERRCODE = '42501';
    END IF;
    SELECT state INTO command_state FROM governance_commands WHERE id = NEW.command_id FOR SHARE;
    IF command_state NOT IN ('CREATED', 'VALIDATED', 'PENDING_APPROVAL', 'APPROVED', 'QUEUED') THEN
      RAISE EXCEPTION 'cancellation request requires an unsigned cancellable command'
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF current_user <> 'bgp_reconciler'
      OR ROW(NEW.command_id, NEW.requested_by, NEW.reason, NEW.request_hash, NEW.created_at)
         IS DISTINCT FROM ROW(OLD.command_id, OLD.requested_by, OLD.reason, OLD.request_hash, OLD.created_at)
      OR OLD.state <> 'REQUESTED'
      OR NEW.state NOT IN ('CONSUMED', 'REJECTED')
      OR NEW.resolved_at IS NULL THEN
      RAISE EXCEPTION 'cancellation intent is immutable and only bgp_reconciler may resolve it'
        USING ERRCODE = '55000';
    END IF;

    SELECT state INTO command_state
    FROM governance_commands
    WHERE id = NEW.command_id
    FOR SHARE;

    IF NEW.state = 'CONSUMED' AND command_state <> 'CANCELLED' THEN
      RAISE EXCEPTION 'cancellation request may be consumed only with a cancelled command'
        USING ERRCODE = '55000';
    END IF;

    IF NEW.state = 'REJECTED' AND command_state NOT IN (
      'SIGNING', 'SUBMITTED', 'CONFIRMED', 'FINALIZED', 'FAILED', 'EXPIRED', 'REJECTED'
    ) THEN
      RAISE EXCEPTION 'pending cancellation cannot be rejected while command remains cancellable'
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'cancellation requests are append-only' USING ERRCODE = '55000';
END;
$$;

CREATE TRIGGER governance_command_cancellation_requests_boundary
BEFORE INSERT OR UPDATE OR DELETE ON governance_command_cancellation_requests
FOR EACH ROW
EXECUTE FUNCTION enforce_governance_command_cancellation_request_boundary();

CREATE TABLE governance_approvals (
  id uuid PRIMARY KEY,
  command_id uuid NOT NULL REFERENCES governance_commands(id),
  admin_user_id uuid NOT NULL REFERENCES admin_users(id),
  decision text NOT NULL CHECK (decision IN ('APPROVE','REJECT')),
  reason text,
  decided_at timestamptz NOT NULL,
  UNIQUE (command_id, admin_user_id)
);

CREATE TABLE signer_nonces (
  environment_id uuid NOT NULL REFERENCES environments(id),
  signer_address evm_address NOT NULL,
  next_nonce bigint NOT NULL CHECK (next_nonce >= 0),
  lease_owner text,
  lease_expires_at timestamptz,
  fencing_token bigint NOT NULL CHECK (fencing_token > 0),
  updated_at timestamptz NOT NULL,
  PRIMARY KEY (environment_id, signer_address)
);

CREATE TABLE governance_tx_attempts (
  id uuid PRIMARY KEY,
  command_id uuid NOT NULL REFERENCES governance_commands(id),
  environment_id uuid NOT NULL REFERENCES environments(id),
  attempt_no integer NOT NULL CHECK (attempt_no > 0),
  signer_address evm_address NOT NULL,
  nonce bigint NOT NULL CHECK (nonce >= 0),
  tx_hash evm_hash,
  raw_tx_hash evm_hash,
  replaces_attempt_id uuid REFERENCES governance_tx_attempts(id),
  state text NOT NULL CHECK (state IN ('SIGNED','BROADCAST','MINED_SUCCESS','MINED_REVERT','REPLACED','DROPPED','FAILED')),
  receipt jsonb,
  submitted_at timestamptz,
  mined_at timestamptz,
  created_at timestamptz NOT NULL,
  UNIQUE (command_id, attempt_no)
);
CREATE UNIQUE INDEX one_live_attempt_per_signer_nonce
  ON governance_tx_attempts(environment_id, signer_address, nonce)
  WHERE state IN ('SIGNED','BROADCAST','MINED_SUCCESS','MINED_REVERT');

CREATE TABLE admin_audit_logs (
  id uuid PRIMARY KEY,
  admin_user_id uuid REFERENCES admin_users(id),
  request_id uuid NOT NULL,
  action text NOT NULL,
  resource_type text,
  resource_id text,
  outcome text NOT NULL CHECK (outcome IN ('ALLOWED','DENIED','SUCCESS','FAILURE')),
  before_value jsonb,
  after_value jsonb,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL
);
CREATE INDEX audit_log_time ON admin_audit_logs(created_at DESC);

CREATE OR REPLACE FUNCTION reject_admin_audit_log_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'admin_audit_logs is append-only: UPDATE and DELETE are forbidden'
    USING ERRCODE = '55000';
END;
$$;

CREATE TRIGGER admin_audit_logs_append_only
BEFORE UPDATE OR DELETE ON admin_audit_logs
FOR EACH ROW
EXECUTE FUNCTION reject_admin_audit_log_mutation();

CREATE TABLE job_runs (
  id uuid PRIMARY KEY,
  environment_id uuid REFERENCES environments(id),
  job_type text NOT NULL,
  dedupe_key text,
  state text NOT NULL CHECK (state IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED','DEAD_LETTER')),
  input jsonb NOT NULL DEFAULT '{}'::jsonb,
  output jsonb,
  error jsonb,
  attempt integer NOT NULL DEFAULT 0 CHECK (attempt >= 0),
  started_at timestamptz,
  finished_at timestamptz,
  created_at timestamptz NOT NULL
);
CREATE UNIQUE INDEX job_dedupe_active
  ON job_runs(job_type, dedupe_key)
  WHERE dedupe_key IS NOT NULL AND state IN ('QUEUED','RUNNING');

CREATE TABLE system_anomalies (
  id uuid PRIMARY KEY,
  environment_id uuid NOT NULL REFERENCES environments(id),
  anomaly_key text NOT NULL,
  severity text NOT NULL CHECK (severity IN ('P0','P1','P2','P3','INFO')),
  status text NOT NULL CHECK (status IN ('OPEN','ACKNOWLEDGED','MITIGATING','RESOLVED','RISK_ACCEPTED')),
  observed_block_number bigint,
  observed_block_hash evm_hash,
  evidence jsonb NOT NULL,
  opened_at timestamptz NOT NULL,
  resolved_at timestamptz
);

ALTER TABLE dividend_approvals
  ADD CONSTRAINT dividend_approvals_admin_user_fk
  FOREIGN KEY (admin_user_id) REFERENCES admin_users(id);

COMMIT;
